package com.adesa.attendance.vendor;
import org.junit.jupiter.api.*;import java.util.*;import com.adesa.attendance.employee.EmployeeRole;import com.adesa.attendance.security.AuthenticatedEmployee;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.mock.env.MockEnvironment;import org.springframework.aop.framework.ProxyFactory;import org.springframework.jdbc.core.JdbcTemplate;import com.fasterxml.jackson.databind.ObjectMapper;import static org.assertj.core.api.Assertions.*;
class VendorAccessTest {
 @AfterEach void cleanup(){SecurityContextHolder.clearContext();}
 @Test void everyNonAdministratorIsDeniedBeforeDatabaseAccess(){var admin=new VendorAdmin(null);for(EmployeeRole role:List.of(EmployeeRole.EMPLOYEE,EmployeeRole.HR)){var principal=new AuthenticatedEmployee(UUID.randomUUID(),"synthetic@example.test","Synthetic",role);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(principal,"",List.of(new SimpleGrantedAuthority("ROLE_"+role),new SimpleGrantedAuthority("ROLE_CAMPAIGN_MANAGE"))));assertThatThrownBy(admin::overview).hasMessageContaining("System Administrator");assertThatThrownBy(admin::links).hasMessageContaining("System Administrator");assertThatThrownBy(()->admin.profile(UUID.randomUUID(),1)).hasMessageContaining("System Administrator");assertThatThrownBy(()->admin.pdf(UUID.randomUUID(),1)).hasMessageContaining("System Administrator");assertThatThrownBy(()->admin.documentTicket(UUID.randomUUID())).hasMessageContaining("System Administrator");}SecurityContextHolder.clearContext();assertThatThrownBy(admin::administrator).hasMessageContaining("System Administrator");}
 @Test void localProfileRejectsProductionDatabaseAndLiveMailBeforeMigration(){var config=new VendorLocalDemo();var env=new MockEnvironment();assertThatThrownBy(()->config.vendorMigrations(env)).isInstanceOf(IllegalStateException.class);env.withProperty("spring.datasource.url",VendorLocalDemo.URL).withProperty("vendor.demo","true").withProperty("adesa.mail.provider","smtp");assertThat(config.vendorMigrations(env)).isNotNull();env.withProperty("vendor.mail.enabled","true");assertThatThrownBy(()->config.vendorMigrations(env)).isInstanceOf(IllegalStateException.class);env.withProperty("vendor.mail.enabled","false").setActiveProfiles("vendor-local","prod");assertThatThrownBy(()->config.vendorMigrations(env)).isInstanceOf(IllegalStateException.class);}
 @Test void serviceCollaboratorsRemainUsableThroughSpringClassProxy(){var db=new JdbcTemplate();var service=new VendorService(db,new ObjectMapper(),new VendorCrypto(Base64.getEncoder().encodeToString(new byte[32])),true,true,"","http://localhost:5180");var factory=new ProxyFactory(service);factory.setProxyTargetClass(true);var proxy=(VendorService)factory.getProxy();assertThat(proxy.jdbc()).isSameAs(db);assertThat(proxy.crypt()).isNotNull();}
}
